package org.kanger;
import java.util.*;
import org.kanger.ContextDependentCutInspection.*;
import org.kanger.ContextDependentModelInspection.*;
import org.kanger.ContextDependentModelInspection.Request;
import org.kanger.ContextDependentModelInspection.Function;
import org.kanger.ContextDependentProductionInspection.Row;
import org.kanger.ContextDependentProductionInspection.TermView;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.enums.ArgumentType;
import org.kanger.interfaces.IArgument;
import org.kanger.units.*;

/** Direct native original formula truth and detached actual carrier truth. No MGU/Arena/discovery calls. */
final class ContextDependentModelAudit {
    private static final class Original {
        final Mind owner;final Rule rule;final Source source;final NativePrenexUnitScope prefix;
        Original(Member member,ContextProductionInventory.Row row,Runnable work)throws Exception{
            owner=member.actual;rule=(Rule)owner.getRules().get(row.nativeRule);source=new Source(member.inventory.context,member.inventory.revision,row.nativeRule,member.inventory.localX,"inventory:"+member.inventory.fingerprint);
            need(rule!=null&&rule.getId()==row.nativeRule&&row.origin.equals(rule.getOrigin())&&!rule.isQuery()&&!rule.isGenerated()&&!rule.isDeleted(owner)&&rule.getTree().size()==1&&!rule.getTree().get(0).isEmpty(),"Whole actual primary single clause required");
            if(rule.getTree().get(0).size()==1&&rule.getTree().get(0).get(0).isAntc())prefix=NativePrenexUnitScope.observeFactoryRow(row.nativeRule,owner,work);
            else {prefix=null;int heads=0;for(Domain d:rule.getTree().get(0)){work.run();need(!d.isSystem(owner)&&!d.isCalculated(owner),"Ordinary native model clause required");if(d.isAntc())heads++;for(IArgument a:d.getArguments()){work.run();if(a.getType()==ArgumentType.TVARIABLE)need(((TVariable)a.getObject(owner)).getRuleId()==rule.getId(),"Actual variable owner required");else need(a.getType()==ArgumentType.TERM&&SemanticTermSnapshot.isOrdinaryValue(a.getValue(owner)),"Flat ordinary native model argument required");}}need(heads<=1,"Supported original Horn clause required");}
        }
    }
    static final class Rejected extends IllegalStateException {Rejected(String why){super(why);}}
    private static void truth(boolean b,String why){if(!b)throw new Rejected(why);}
    private final Runnable originalBudget,sharedBudget;
    private static Runnable combined(Runnable local,Runnable shared){return ()->{local.run();shared.run();};}
    final Request request;final Map<String,List<Original>> originals=new LinkedHashMap<>();final Map<String,List<Row>> finals=new LinkedHashMap<>();final Map<Function,Integer> declarations=new LinkedHashMap<>();final Set<Source> sources=new HashSet<>();
    private static void need(boolean b,String message){if(!b)throw new IllegalStateException(message);}
    private static void interrupt()throws InterruptedException{if(Thread.currentThread().isInterrupted())throw new InterruptedException("Dependent model audit interrupted");}
    ContextDependentModelAudit(Member x,List<Cut> cuts,ContextDependentIterationInspection.Result iteration,Request request)throws Exception{
        this(x,cuts,iteration.checked,request);
    }
    /** Exact checked receiving history; does not manufacture a fixed-point iteration result. */
    ContextDependentModelAudit(Member x,List<Cut> cuts,ContextDependentRoundInspection.Result checked,Request request)throws Exception{
        this(x,cuts,checked,request,()->{});
    }
    ContextDependentModelAudit(Member x,List<Cut> cuts,ContextDependentRoundInspection.Result checked,Request request,Runnable shared)throws Exception{
        this.request=request;sharedBudget=shared;originalBudget=combined(ContextGroundProductionRounds.budget(request.originalWork),shared);Runnable work=originalBudget;List<Member> members=new ArrayList<>();members.add(x);for(Cut cut:cuts)members.addAll(cut.members);Map<UUID,List<Original>> physical=new LinkedHashMap<>();
        for(Member member:members){work.run();need(member.inventory.dependentPrimaryView(),"Whole primary-only physical model view required");List<Original> rows=new ArrayList<>();for(ContextProductionInventory.Row row:member.inventory.rows){work.run();Original original=new Original(member,row,work);need(sources.add(original.source),"Unique physical original occurrence required");rows.add(original);if(original.prefix!=null)for(int i=0;i<original.prefix.binders.size();i++){work.run();NativePrenexUnitScope.Binder b=original.prefix.binders.get(i);if(!b.universal)need(declarations.put(new Function(original.source,i),b.precedingUniversals.size())==null,"Unique function declaration required");}}need(physical.put(member.inventory.context,rows)==null,"Distinct physical members required");}
        originals.put(ContextDependentCutInspection.local(x.inventory.context),new ArrayList<>(physical.get(x.inventory.context)));for(Cut cut:cuts){List<Original> rows=new ArrayList<>(physical.get(x.inventory.context));for(Member member:cut.members)rows.addAll(physical.get(member.inventory.context));need(originals.put(cut.key,rows)==null,"Whole exact cut model required");}
        need(checked!=null&&!checked.barriers.isEmpty(),"Whole checked receiving history required");ContextDependentRoundInspection.Barrier barrier=checked.barriers.get(checked.barriers.size()-1);need(originals.keySet().equals(barrier.cuts.keySet())&&originals.keySet().equals(request.models.keySet()),"One model per exact actual cut required");
        for(String cut:originals.keySet()){List<Row> rows=new ArrayList<>();for(ContextDependentRoundInspection.Ticket ticket:barrier.common){work.run();Row row=barrier.observed.get(ticket);need(row!=null,"Every actual common proof occurrence required");rows.add(row);}rows.addAll(barrier.cuts.get(cut).products);finals.put(cut,rows);}
        int cells=0;for(String cut:originals.keySet()){
            interrupt();Model model=request.models.get(cut);need(model.points.size()<=request.points,"Named model point limit");for(int i=0;i<model.points.size();i++){work.run();need(!model.points.get(i).semanticallyEquals(model.otherRepresentative),"Concrete ALL-other representative must be outside named basis");for(int j=0;j<i;j++){work.run();need(!model.points.get(i).semanticallyEquals(model.points.get(j)),"Distinct typed named points required");}}
            for(Map.Entry<Signature,Relation> e:model.relations.entrySet()){work.run();need(++cells<=request.cells,"Whole family relation/function table bound");for(List<Integer> tuple:e.getValue().exceptions.keySet()){need(++cells<=request.cells,"Whole family exception bound");tuple(tuple,e.getKey().arity,model,work);}}
            for(Map.Entry<Function,Choice> e:model.functions.entrySet()){work.run();need(++cells<=request.cells,"Whole family function table bound");Integer arity=declarations.get(e.getKey());Choice f=e.getValue();need(arity!=null&&f.arity==arity&&f.otherwise<=model.points.size(),"Exact original Source/binder and preceding-universal function rank required");for(Map.Entry<List<Integer>,Integer> row:f.exceptions.entrySet()){need(++cells<=request.cells,"Whole family function exception bound");tuple(row.getKey(),arity,model,work);need(row.getValue()>=0&&row.getValue()<=model.points.size(),"Total function output class required");}}
            Set<Signature> vocabulary=new HashSet<>();Set<Function> functions=new HashSet<>();for(Original original:originals.get(cut))shape(original,model,vocabulary,functions,work);for(Row row:finals.get(cut))shape(row,model,vocabulary,functions,work);need(vocabulary.equals(model.relations.keySet())&&functions.equals(model.functions.keySet()),"No missing/extra model signatures or function declarations");
        }
    }
    private static void tuple(List<Integer> tuple,int arity,Model model,Runnable work){need(tuple.size()==arity,"Exact model tuple arity required");for(int p:tuple){work.run();need(p>=0&&p<=model.points.size(),"Named/ALL-other tuple class required");}}
    private static int fixed(Model model,SemanticTermSnapshot value,Runnable work){for(int i=0;i<model.points.size();i++){work.run();if(model.points.get(i).semanticallyEquals(value))return i;}throw new IllegalStateException("EVERY actual typed constant must occur in named basis");}
    private static Signature signature(Domain d,Mind m)throws Exception{return new Signature(d.getPredicate(m).getName(m),d.getRange());}
    private static void shape(Original original,Model model,Set<Signature> vocabulary,Set<Function> functions,Runnable work)throws Exception{
        if(original.prefix!=null){NativePrenexUnitScope p=original.prefix;vocabulary.add(new Signature(p.predicate,p.slots.size()));for(int i=0;i<p.binders.size();i++){work.run();if(!p.binders.get(i).universal)functions.add(new Function(original.source,i));}for(NativePrenexUnitScope.Slot s:p.slots){work.run();if(s.binder<0)fixed(model,s.value,work);}return;}
        for(Domain d:original.rule.getTree().get(0)){work.run();vocabulary.add(signature(d,original.owner));for(IArgument a:d.getArguments()){work.run();if(a.getType()!=ArgumentType.TVARIABLE)fixed(model,SemanticTermSnapshot.capture(a.getValue(original.owner)),work);}}
    }
    private void shape(Row row,Model model,Set<Signature> vocabulary,Set<Function> functions,Runnable work){
        work.run();need(row!=null&&sources.contains(row.rule)&&row.sources.contains(row.rule)&&!row.sources.isEmpty(),"Actual carrier producer and whole support required");for(Source s:row.sources){work.run();need(sources.contains(s),"Actual whole physical carrier Sources required");}vocabulary.add(new Signature(row.predicate,row.arguments.size()));Deque<TermView> pending=new ArrayDeque<>(row.arguments);Set<TermView> seen=Collections.newSetFromMap(new IdentityHashMap<TermView,Boolean>());
        while(!pending.isEmpty()){work.run();TermView t=pending.pop();if(!seen.add(t))continue;switch(t.kind){case VARIABLE:need(t.variable>=0,"Exact final variable required");break;case VALUE:fixed(model,t.value,work);break;case APPLICATION:Function f=new Function(t.symbolSource,t.binder);Integer arity=declarations.get(f);need(arity!=null&&arity==t.arguments.size()&&row.sources.contains(f.source),"Actual function Source/binder/dependency arity and ancestry required");functions.add(f);for(TermView child:t.arguments){work.run();pending.push(child);}break;default:throw new IllegalStateException("Unknown actual term shape");}}
    }
    private static boolean relation(Model m,String name,List<Integer> tuple,Runnable work){work.run();Relation r=m.relations.get(new Signature(name,tuple.size()));need(r!=null,"Complete relation interpretation required");Boolean value=r.exceptions.get(tuple);return value==null?r.otherwise:value;}
    private static int choice(Model m,Function f,List<Integer> tuple,Runnable work){work.run();Choice table=m.functions.get(f);need(table!=null&&table.arity==tuple.size(),"Exact total dependency function required");Integer value=table.exceptions.get(tuple);return value==null?table.otherwise:value;}
    private interface Truth {void check(Map<Long,Integer> assignment)throws Exception;}
    /** Original quantifier/ordinary-variable DFS; classes include ALL unmentioned values. */
    private static void universal(List<Long> ids,Model model,Runnable work,Truth truth)throws Exception{
        int[] digits=new int[ids.size()];Map<Long,Integer> assignment=new HashMap<>();int level=0;while(level>=0){work.run();if(level==ids.size()){truth.check(assignment);level--;if(level>=0)digits[level]++;continue;}if(digits[level]>model.points.size()){assignment.remove(ids.get(level));level--;if(level>=0)digits[level]++;continue;}assignment.put(ids.get(level),digits[level]);level++;if(level<ids.size())digits[level]=0;}
    }
    private static void original(Original o,Model model,Runnable work)throws Exception{
        if(o.prefix!=null){NativePrenexUnitScope p=o.prefix;Relation r=model.relations.get(new Signature(p.predicate,p.slots.size()));if(r.exceptions.isEmpty()){truth(r.otherwise,"Uniform original positive unit false");return;}List<Long> ids=new ArrayList<>();for(int i=0;i<p.binders.size();i++){work.run();if(p.binders.get(i).universal)ids.add((long)i);}universal(ids,model,work,assignment->{List<Integer> binders=new ArrayList<>();for(int i=0;i<p.binders.size();i++){work.run();NativePrenexUnitScope.Binder b=p.binders.get(i);if(b.universal)binders.add(assignment.get((long)i));else{List<Integer> args=new ArrayList<>();for(int d:b.precedingUniversals){work.run();args.add(binders.get(d));}binders.add(choice(model,new Function(o.source,i),args,work));}}List<Integer> args=new ArrayList<>();for(NativePrenexUnitScope.Slot s:p.slots){work.run();args.add(s.binder<0?fixed(model,s.value,work):binders.get(s.binder));}truth(relation(model,p.predicate,args,work),"Original quantified unit false on named/ALL-other assignment");});return;}
        List<Domain> clause=o.rule.getTree().get(0);Set<Long> variables=new LinkedHashSet<>();for(Domain d:clause){work.run();Relation r=model.relations.get(signature(d,o.owner));if(r.exceptions.isEmpty()&&r.otherwise==d.isAntc())return;for(IArgument a:d.getArguments()){work.run();if(a.getType()==ArgumentType.TVARIABLE)variables.add(((TVariable)a.getObject(o.owner)).getId());}}
        universal(new ArrayList<>(variables),model,work,assignment->{boolean yes=false;for(Domain d:clause){List<Integer> tuple=new ArrayList<>();for(IArgument a:d.getArguments()){work.run();tuple.add(a.getType()==ArgumentType.TVARIABLE?assignment.get(((TVariable)a.getObject(o.owner)).getId()):fixed(model,SemanticTermSnapshot.capture(a.getValue(o.owner)),work));}yes|=relation(model,d.getPredicate(o.owner).getName(o.owner),tuple,work)==d.isAntc();}truth(yes,"Original whole clause false on Cartesian named/ALL-other assignment");});
    }
    int original()throws Exception{Runnable work=originalBudget;int count=0;for(String cut:originals.keySet())for(Original o:originals.get(cut)){interrupt();work.run();original(o,request.models.get(cut),work);count++;}return count;}
    private static int value(TermView root,Model model,Map<Integer,Integer> variables,Runnable work){IdentityHashMap<TermView,Integer> values=new IdentityHashMap<>();Deque<TermView> pending=new ArrayDeque<>();pending.push(root);while(!pending.isEmpty()){work.run();TermView t=pending.peek();if(values.containsKey(t)){pending.pop();continue;}if(t.kind==ContextDependentProductionInspection.Kind.VARIABLE){Integer v=variables.get(t.variable);need(v!=null,"Every final variable assignment required");values.put(t,v);pending.pop();}else if(t.kind==ContextDependentProductionInspection.Kind.VALUE){values.put(t,fixed(model,t.value,work));pending.pop();}else{boolean ready=true;for(TermView child:t.arguments){work.run();if(!values.containsKey(child)){pending.push(child);ready=false;break;}}if(ready){List<Integer> args=new ArrayList<>();for(TermView child:t.arguments){work.run();args.add(values.get(child));}values.put(t,choice(model,new Function(t.symbolSource,t.binder),args,work));pending.pop();}}}return values.get(root);}
    /** Actual graph evaluation uses an odometer, independently of original quantifier DFS and MGU code. */
    static void unit(Row row,Model model,Runnable work)throws Exception{
        Relation relation=model.relations.get(new Signature(row.predicate,row.arguments.size()));need(relation!=null,"Actual carrier relation required");if(relation.exceptions.isEmpty()){truth(relation.otherwise==row.positive,"Uniform actual signed carrier false");return;}
        Set<Integer> ids=new LinkedHashSet<>();Deque<TermView> pending=new ArrayDeque<>(row.arguments);Set<TermView> seen=Collections.newSetFromMap(new IdentityHashMap<TermView,Boolean>());while(!pending.isEmpty()){work.run();TermView t=pending.pop();if(!seen.add(t))continue;if(t.kind==ContextDependentProductionInspection.Kind.VARIABLE)ids.add(t.variable);for(TermView child:t.arguments){work.run();pending.push(child);}}List<Integer> keys=new ArrayList<>(ids);int[] digits=new int[keys.size()];boolean more=true;while(more){work.run();Map<Integer,Integer> assignment=new HashMap<>();for(int i=0;i<keys.size();i++){work.run();assignment.put(keys.get(i),digits[i]);}List<Integer> tuple=new ArrayList<>();for(TermView argument:row.arguments)tuple.add(value(argument,model,assignment,work));truth(relation(model,row.predicate,tuple,work)==row.positive,"Actual final signed carrier false on named/ALL-other assignment");more=false;for(int i=0;i<digits.length;i++){work.run();if(++digits[i]<=model.points.size()){more=true;break;}digits[i]=0;}}
    }
    int finalModel()throws Exception{Runnable work=combined(ContextGroundProductionRounds.budget(request.finalWork),sharedBudget);int count=0;for(String cut:finals.keySet())for(Row row:finals.get(cut)){interrupt();work.run();need(++count<=request.cells,"Every actual common/private occurrence obligation must fit");unit(row,request.models.get(cut),work);}return count;}
    int original(String cut)throws Exception{List<Original> rows=originals.get(cut);need(rows!=null,"Exact audited search cut required");int count=0;for(Original o:rows){interrupt();originalBudget.run();original(o,request.models.get(cut),originalBudget);count++;}return count;}
    int finalModel(String cut)throws Exception{List<Row> rows=finals.get(cut);need(rows!=null,"Exact audited search cut required");Runnable work=combined(ContextGroundProductionRounds.budget(request.finalWork),sharedBudget);int count=0;for(Row row:rows){interrupt();work.run();need(++count<=request.cells,"Every actual common/private occurrence obligation must fit");unit(row,request.models.get(cut),work);}return count;}

}
